# Bug Report
 🔎 Search Terms
Assert, This, Class, Method
 🕗 Version & Regression Information
All versions including current Nightly (5.0.0)
- This is the behavior in every version I tried, and I reviewed the FAQ for entries about Assert and This
 ⏯ Playground Link
[Playground link with relevant code](
 💻 Code
ts
function assert(
 condition: unknown,
): asserts condition {
 if (!condition) {
 throw new Error();
 }
}
class MyClass {
 private map = {
 my_key: 'example_value'
 }
 runTypeFails() {
 const params = null as any as { a: { key: string } } | null
 assert(params)
 type Key = keyof typeof this.map // Cannot find name 'this' here
 this.map[params.a.key as Key] }
 runTypeWorks1() {
 type Key = keyof typeof this.map // Works
 const params = null as any as { a: { key: string } } | null
 assert(params)
 this.map[params.a.key as Key]
 }
 runTypeWorks2(params: { a: { key: string } } | null) {
 assert(params)
 type Key = keyof typeof this.map // Works
 this.map[params.a.key as Key]
 }
}
 🙁 Actual behavior
Typescript cannot find 'this' after asserting local variable exists
 🙂 Expected behavior
Should be able to fin any 'this' and run

