 method: F,
 ...args: A
): (...args: RemainingParams<A, Parameters<F>>) => ReturnType<F> | void;
export function bind<F extends AnyFn, A extends PartialParams<Parameters<F>>>(
 method: F,
 ...args: A
): (...args: RemainingParams<A, Parameters<F>>) => ReturnType<F> | void;
export function bind<
 T,
 U extends keyof T,
 A extends T[U] extends AnyFn ? PartialParams<Parameters<T[U]>> : []
>(
 target: T,
 method: U,
 ...args: A
): T[U] extends AnyFn
 ? (...args: RemainingParams<A, Parameters<T[U]>>) => ReturnType<T[U]> | void
 : never;
// overload implementation
export function bind(...curried: any[]): any {
 // ...
}
// TYPE UTILITIES //
export type AnyFn = (...args: any[]) => any;
type PartialParams<P extends any[]> = P extends [infer First, ...infer Rest]
 ? [] | [First] | [First, ...PartialParams<Rest>]
 : // This is necessary to handle optional tuple values
 Required<P> extends [infer First, ...infer Rest]
 ? [] | [First | undefined] | [First | undefined, ...PartialParams<Partial<Rest>>]
 : never;
type RemainingParams<PartialParams extends any[], All extends any[]> = PartialParams extends [
 infer First,
 ...infer Rest
]
 ? All extends [infer AllFirst, ...infer AllRest]
 ? First extends AllFirst
 ? RemainingParams<Rest, AllRest>
 : never
 : // This is necessary to handle optional tuple values
 Required<All> extends [infer AllFirst, ...infer AllRest]
 ? First extends AllFirst | undefined
 ? Partial<RemainingParams<Rest, AllRest>>
 : never
 : never
 : PartialParams extends []
 ? All
 : never;
 🙁 Actual behavior
Wellllll the overload isn't working anymore.
 🙂 Expected behavior
I *think* I expected this overload to keep working.

description:
# Bug Report
 🔎 Search Terms
- required
- arrow
 🕗 Version & Regression Information
In typecript generated type (d.ts) they is an error while using `Required` in `[K in keyof Required<T>]` in a arrow function definition
- This changed between versions 4.6.4 and newer version of typescript
 ⏯ Playground Link
 💻 Code
<!-- Please post the relevant code sample here as well-->
ts
export const test2 = <T = Record<string, never>>(schema: {
 [K in keyof Required<T>]: T[K];
}) => {
 console.log(schema);
}
export function test1<T = Record<string, never>>(schema: {
 [K in keyof Required<T>]: T[K];
}) {
 console.log(schema);
};
 🙁 Actual behavior
In typescript 4.6.4 the d.ts file look like this:
ts
export declare const test2: <T = Record<string, never>>(schema: { [K in keyof Required<T>]: T[K]; }) => void;
export declare function test1<T = Record<string, never>>(schema: {
 [K in keyof Required<T>]: T[K];
}): void;
And starting from 4.7 the d.ts file look like this:
ts
export declare const test2: <T = Record<string, never>>(schema: Required<T> extends infer T_1 ? { [K in keyof T_1]: T[K]; } : never) => void;
export declare function test1<T = Record<string, never>>(schema: {
 [K in keyof Required<T>]: T[K];
}): void;
 🙂 Expected behavior
This should be compiled to the same output as the 4.6 version

