[Playground link with relevant code](
 💻 Code
ts
interface Props {
 innerObject?: {
 innerObject2?: {
 name?: string;
 email?: string;
 }
 };
}
// won't let name and email default to undefined
// Initializer provides no value for this binding element and the binding element has no default value. export const nestedDestructure1 = (props: Props) => {
 const {
 innerObject: {
 innerObject2: { name, email } = {}
 } = {}
 } = props;
 console.log(name, email);
};
 🙁 Actual behavior
Initializer provides no value for this binding element and the binding element has no default value.(2525)
 🙂 Expected behavior
