description:
🔎 Search Terms
In [`processTaggedTemplateExpression`]( the code checks whether the tagged template expression using the [`hasInvalidEscape` function](
 This was done in to support a new feature in tagged template literals allowing for invalid escape sequences.
Unfortunately, the function was written in a way that relies on implicit from `number` -> `boolean` instead of masking the `templateFlags` field:
typescript
/** @internal */
export function hasInvalidEscape(template: TemplateLiteral): boolean {
 return template && !!(isNoSubstitutionTemplateLiteral(template)
 ? template.templateFlags
 : (template.head.templateFlags || some(template.templateSpans, span => !!span.literal.templateFlags)));
}
This means the code assumes any template literal with non-zero flags contains an invalid escape. While this was true in the past, [new flags were introduced in 5.1]( breaking the logic of the code. Now all tagged templates containing unicode escape sequences now get transpiled when they don't need to, causing a code size increase.
 🕗 Version & Regression Information
This changed between versions 5.0.4 and 5.1.6
v5.0.4: v5.1.6: ⏯ Playground Link
 💻 Code
ts
function foo<T>(a: T){return a;}
const a = foo`\u0000`;
const b = foo`a`;
 🙁 Actual behavior
"use strict";
var __makeTemplateObject = (this && this.__makeTemplateObject) || function (cooked, raw) {
 if (Object.defineProperty) { Object.defineProperty(cooked, "raw", { value: raw }); } else { cooked.raw = raw; }
 return cooked;
};
function foo(a) { return a; }
const a = foo(__makeTemplateObject(["\0"], ["\\u0000"]));
const b = foo `a`;
 🙂 Expected behavior
"use strict";
function foo(a) { return a; }
const a = foo `\u0000`;
const b = foo `a`;

text:
Bug Title: New Template Literal Flags are confused for `ContainsInvalidEscape` causing tagged template expressions to be unnecessarily transpiled
Bug Description: 🔎 Search Terms
In [`processTaggedTemplateExpression`]( the code checks whether the tagged template expression using the [`hasInvalidEscape` function](
 This was done in to support a new feature in tagged template literals allowing for invalid escape sequences.
Unfortunately, the function was written in a way that relies on implicit from `number` -> `boolean` instead of masking the `templateFlags` field:
typescript
/** @internal */
export function hasInvalidEscape(template: TemplateLiteral): boolean {
 return template && !!(isNoSubstitutionTemplateLiteral(template)
 ? template.templateFlags
 : (template.head.templateFlags || some(template.templateSpans, span => !!span.literal.templateFlags)));
}
This means the code assumes any template literal with non-zero flags contains an invalid escape. While this was true in the past, [new flags were introduced in 5.1]( breaking the logic of the code. Now all tagged templates containing unicode escape sequences now get transpiled when they don't need to, causing a code size increase.
 🕗 Version & Regression Information
This changed between versions 5.0.4 and 5.1.6
v5.0.4: v5.1.6: ⏯ Playground Link
 💻 Code
ts
function foo<T>(a: T){return a;}
const a = foo`\u0000`;
const b = foo`a`;
 🙁 Actual behavior
"use strict";
var __makeTemplateObject = (this && this.__makeTemplateObject) || function (cooked, raw) {
 if (Object.defineProperty) { Object.defineProperty(cooked, "raw", { value: raw }); } else { cooked.raw = raw; }
 return cooked;
};
function foo(a) { return a; }
const a = foo(__makeTemplateObject(["\0"], ["\\u0000"]));
const b = foo `a`;
 🙂 Expected behavior
"use strict";
function foo(a) { return a; }
const a = foo `\u0000`;
const b = foo `a`;

description:
🔎 Search Terms
type definitions invalid name
 🕗 Version & Regression Information
- This is the behavior since TypeScript 4.0, worked in 3.9.10
 ⏯ Playground Link
 💻 Code
> test/Test.js
js
/** @module test/Test */
class Test {}
export default Test;
> Test.js
js
/** @module Test */
class Test {}
export default Test;
> X.js
js
import Test from './test/Test.js'
/**
 * @typedef {Object} Options
 * @property {typeof import("./Test.js").default} [test]
 */
class X extends Test {
 /**
 * @param {Options} options
 */
 constructor(options) {
 super();
 if (options.test) {
 this.test = new options.test();
 }
 }
}
export default X;
 🙁 Actual behavior
In the generate file there is a reference to a wrong class name (`Test_1`)
> X.d.ts
ts
export default X;
export type Options = {
 test?: typeof import("./Test.js").default | undefined;
};
/**
 * @typedef {Object} Options
 * @property {typeof import("./Test.js").default} [test]
 */
declare class X extends Test {
 /**
 * @param {Options} options
 */
 constructor(options: Options);
 test: import("./Test.js").default | undefined;
}
import Test_1 from './test/Test.js';
//# sourceMappingURL=X.d.ts.map
 🙂 Expected behavior
The class in the import statement should be named `Test`.

