ts
{
 type Something = {
 a?: string;
 };
 const x: Something = {};
 function assignToKey(key: keyof Something, value: string | undefined) {
 x[key] = value; // error
 x.a = value; // error
 x['a'] = value; // error
 }
 assignToKey('a', undefined);
}
{
 type Something = {
 a?: string;
 b?: string;
 };
 const x: Something = {};
 function assignToKey(key: keyof Something, value: string | undefined) {
 x[key] = value; // no error
 x.a = value; // error
 x['a'] = value; // error
 }
 assignToKey('a', undefined);
}
 🙁 Actual behavior
Assigning `undefined` to properties when using variable as key shows no error, where the type of the variable is a union of strings.
Accessing a particular property and assigning `undefined` shows error.
If the variable used as key name has the type as a single string, it shows error.
 🙂 Expected behavior
Should show error consitently across all cases.
 Additional information about the issue
_No response_

