 | { type: 'b' };
function example1(value: Union): { type: 'a'; variant: 2 } | null {
 if (value.type !== 'a') {
 return null;
 }
 if (value.variant 1) {
 return null;
 }
 return value;
}
function example2(value: Union): { type: 'a'; variant: 2 } | null {
 if (value.type !== 'a') {
 return null;
 }
 if (
 value.type 'a' && // should always be true
 value.variant 1
 ) {
 return null;
 }
