 const promises = await Promise.allSettled(fn());
 return promises.map((result) =>
 result.status 'fulfilled'
 ? [result.value, undefined]
 : [undefined, new Error(String(result.reason))]
 ) as { [K in keyof T]: [Awaited<T[K]>, undefined] | [undefined, Error] };
}
async function test() {
 const [[p1, p1Error], _,] = await myAllSettled(() => [
 Promise.resolve(0), Promise.reject(1)
 ] as const);
 if (p1Error) return;
 // HELP!: How can I make (p1, p1Error) types be dependant so p1 can be inferred as `number` instead of `number | undefined`
 // I want to keep the dx of inlining the destructuring in line 18
 console.log(p1);
}
 💻 Use Cases
1. I want to write a nice dx over Promise.allSettled returning a tuple of [value, error] such that they are dependent on each other
2. I want to be able to preserve the inline destructuring so that typescript is able to infer the type of `p1` as `number` instead of `number | undefined`
3. A workaround is to not inline the destructuring fully (see below) but comes at the cost of a extra line and a hit to dx
eg:
ts
async function test() {
 const [p1Result, _,] = await myAllSettled(() => [
 Promise.resolve(0), Promise.reject(1)
 ] as const);
 // Destructure again on a new line
 const [p1, p1Error] = p1Result;
 if (p1Error) return;
 // p1 is now correctly inferred as `number` instead of `number | undefined`
 console.log(p1);
}

description:
🔎 Search Terms
parameter symbol assignment binding pattern dependent narrowing variables
 🕗 Version & Regression Information
- This is the behavior in every version I tried
 ⏯ Playground Link
 💻 Code
ts
function test([x, y]: [1, 2] | [3, 4]) {
 if (Math.random()) {
 y = 2;
 }
 if (y 2) {
 x
 // ^? (parameter) x: 1
 }
}
// an example valid call that might lead to a runtime error in the called function
test([3, 4]);
 🙁 Actual behavior
Assignment to `y` keeps narrowing `x` as if `y` was never mutated. Effectively the binding pattern in this parameter is treated as `const` variable
 🙂 Expected behavior
I'd expect this assignment to prevent dependent narrowing altogether.
 Additional information about the issue
Assignment to `x` actually prevents dependent narrowing in a scenario like this: [TS playground]( It's just that those assignments are tracked per symbol and not per the root declaration. I believe that the simplest fix would be to just mark the whole root declaration as reassigned and treat all contained variables as non-const based on that.

