class Foo {
 public static bar() { }
}
 🙁 Actual behavior
Getting the following error when the generated JS is run.
> Cannot read properties of undefined (reading 'bar') 🙂 Expected behavior
The generated code should work. Otherwise, the tsc should at least throw compilation error.
 Additional information about the issue
This happens because the class decorators are listed, before the class is defined.
js
let Foo = (() => {
 let _classDecorators = [deco(Foo.bar)]; // this seems to be causing the issue.
 let _classDescriptor;
 let _classExtraInitializers = [];
 let _classThis;
 var Foo = class {
 static { _classThis = this; }
 static {
 const _metadata = typeof Symbol "function" && Symbol.metadata ? Object.create(null) : void 0;
 __esDecorate(null, _classDescriptor = { value: _classThis }, _classDecorators, { kind: "class", name: _classThis.name, metadata: _metadata }, null, _classExtraInitializers);
 Foo = _classThis = _classDescriptor.value;
 if (_metadata) Object.defineProperty(_classThis, Symbol.metadata, { enumerable: true, configurable: true, writable: true, value: _metadata });
 __runInitializers(_classThis, _classExtraInitializers);
 }
 static bar() { }
 };
 return Foo = _classThis;
})();

text:
Bug Title: Using static members in class decorator
Bug Description: 🔎 Search Terms
TC39 decorators, class decorator, static members
 🕗 Version & Regression Information
This changed when started using the new TC39 decorators (non-experimental/legacy).
 ⏯ Playground Link
 💻 Code
ts
function deco(hook?: any): any { }
@deco(Foo.bar)
class Foo {
 public static bar() { }
}
 🙁 Actual behavior
Getting the following error when the generated JS is run.
> Cannot read properties of undefined (reading 'bar') 🙂 Expected behavior
The generated code should work. Otherwise, the tsc should at least throw compilation error.
 Additional information about the issue
This happens because the class decorators are listed, before the class is defined.
js
let Foo = (() => {
 let _classDecorators = [deco(Foo.bar)]; // this seems to be causing the issue.
 let _classDescriptor;
 let _classExtraInitializers = [];
 let _classThis;
 var Foo = class {
 static { _classThis = this; }
 static {
 const _metadata = typeof Symbol "function" && Symbol.metadata ? Object.create(null) : void 0;
 __esDecorate(null, _classDescriptor = { value: _classThis }, _classDecorators, { kind: "class", name: _classThis.name, metadata: _metadata }, null, _classExtraInitializers);
 Foo = _classThis = _classDescriptor.value;
 if (_metadata) Object.defineProperty(_classThis, Symbol.metadata, { enumerable: true, configurable: true, writable: true, value: _metadata });
 __runInitializers(_classThis, _classExtraInitializers);
 }
 static bar() { }
 };
 return Foo = _classThis;
})();

description:
🔎 Search Terms
constructor narrow
 🕗 Version & Regression Information
- This is the behavior in every version I tried, and I reviewed the FAQ for entries about ___constructors______
 ⏯ Playground Link
 💻 Code
ts
function foo<T extends string | (new () => {})>(a: T){
 if (typeof a !== 'string') {
 new a()
 // ^?
 // This expression is not constructable.
 // Not all constituents of type 'string | (new () => {})' are constructable.
 // Type 'string' has no construct signatures.(2351)
 }
}
function bar<T extends string | (() => void)>(a: T){
 if (typeof a !== 'string') {
 a()
// ^?
// OK
 }
}
class A {}
foo(A)
bar(() => void 0)
 🙁 Actual behavior
The type narrowing for the generic union constraint works if it is normal function,
but not constructors
 🙂 Expected behavior
I'd expect they both to work, or both not to work.
 Additional information about the issue
_No response_

