description:
🔎 Search Terms
"switch default undefined", "switch exactOptionalPropertyTypes
 🕗 Version & Regression Information
- This is the behavior in every version I tried, and I reviewed the FAQ for entries about type guards.
 ⏯ Playground Link
 💻 Code
ts
interface A {
 optionalProp?: "hello";
}
function func(arg: A) {
 const { optionalProp } = arg;
 switch(optionalProp) { case undefined:
 return undefined
 case "hello":
 return "hello";
 default: assertUnreachable(optionalProp)
 // ^const optionalProp: undefined
 // ^should be type: "never"
 }
}
function assertUnreachable(_: never): never {
 throw new Error("Unreachable path taken");
}
 🙁 Actual behavior
`optionalProp` is of type `undefined` in the default case
 🙂 Expected behavior
`optionalProp` should be of type `never` in the default case
 Additional information about the issue
Need to set the configuration option `exactOptionalPropertyTypes` to `true`.
It's working as intended when set to `false`

