 self: Kind<F, R1, O1, E1, A>,
 that: Kind<F, R2, O2, E2, B>,
 f: (a: A, b: B) => C
 ): Kind<F, R1 & R2, O1 | O2, E1 | E2, C>
} =>
 dual(
 3,
 <R1, O1, E1, A, R2, O2, E2, B, C>(
 self: Kind<F, R1, O1, E1, A>,
 that: Kind<F, R2, O2, E2, B>,
 f: (a: A, b: B) => C
 ): Kind<F, R1 & R2, O1 | O2, E1 | E2, C> => F.map(F.product(self, that), ([a, b]) => f(a, b))
 )
export const zipRight = <F extends TypeLambda>(F: SemiApplicative<F>): {
 <R2, O2, E2, B>(
 that: Kind<F, R2, O2, E2, B>
 ): <R1, O1, E1, _>(self: Kind<F, R1, O1, E1, _>) => Kind<F, R1 & R2, O2 | O1, E2 | E1, B>
 <R1, O1, E1, _, R2, O2, E2, B>(
 self: Kind<F, R1, O1, E1, _>,
 that: Kind<F, R2, O2, E2, B>
 ): Kind<F, R1 & R2, O1 | O2, E1 | E2, B>
} =>
 dual(2, <R1, O1, E1, _, R2, O2, E2, B>(
 self: Kind<F, R1, O1, E1, _>,
 that: Kind<F, R2, O2, E2, B>
 ): Kind<F, R1 & R2, O1 | O2, E1 | E2, B> => zipWith(F)(self, that, SK))
 🙁 Actual behavior
Declaration emit is
ts
export declare const zipRight: <F extends TypeLambda>(F: SemiApplicative<F>) => {
 <R2, O2, E2, B>(that: Kind<F, R2, O2, E2, B>): <R1, O1, E1, _>(self: Kind<F, R1, O1, E1, _>) => Kind<F, R1 & R2, O2 | O1, E2 | E1, B>;
 <R1, O1, E1, _, R2, O2, E2, B>(self: Kind<F, R1, O1_1, E1_1, __1>, that: Kind<F, R2, O2_1, E2_1, B_1>): Kind<F, R1 & R2, O1_1 | O2_1, E1_1 | E2_1, B_1>;
};
 🙂 Expected behavior
Declaration emit is
ts
export declare const zipRight: <F extends TypeLambda>(F: SemiApplicative<F>) => {
 <R2, O2, E2, B>(that: Kind<F, R2, O2, E2, B>): <R1, O1, E1, _>(self: Kind<F, R1, O1, E1, _>) => Kind<F, R1 & R2, O2 | O1, E2 | E1, B>;
 <R1_1, O1_1, E1_1, __1, R2_1, O2_1, E2_1, B_1>(self: Kind<F, R1_1, O1_1, E1_1, __1>, that: Kind<F, R2_1, O2_1, E2_1, B_1>): Kind<F, R1_1 & R2_1, O1_1 | O2_1, E1_1 | E2_1, B_1>;
};
as in 5.4.5 or semantically equivalent. Or at least correct.
 Additional information about the issue
_No response_

description:
🔎 Search Terms
jsdoc private constructor
 🕗 Version & Regression Information
- This is the behavior in every version I tried back through TS 3.8 where JSDoc support was added, and I reviewed the FAQ for entries about JSDoc
 ⏯ Playground Link
 💻 Code
js
// foo.js
class Foo {
 /**
 * @private
 */
 constructor() {}
}
new Foo()
// Constructor of class 'Foo' is private and only accessible within the class declaration.(2673)
 🙁 Actual behavior
Emits the declaration file:
ts
declare class Foo {
}
 🙂 Expected behavior
Should emit the declaration file:
ts
declare class Foo {
 /**
 * @private
 */
 private constructor();
}
 Additional information about the issue
I ran into this as it was requested that TypeDoc add a new JSDoc tag to work around this issue. This seems wrong since the declaration file doesn't accurately describe the types within the file, but it's also very unfortunate that it results in the loss of any documentation added to the constructor.

